"use client"
import React from "react";
import { useWishlist } from "@/store/wishlistStore";
import { useCart } from "@/store/cartStore";
import { toast } from "react-toastify";
import EmptyCart from "@/components/EmptyCart"
import ProductCard from "@/components/ProductCard";

function WishlistPage() {

  const { wishlistItems, removeWishlistItem } = useWishlist();
  const { cartItems, addCartItem } = useCart();

  const handleAddToCart = (item) => {
    const isInCart = cartItems.some((cartItem) => cartItem.id === item.id);

    if (!isInCart) {
      addCartItem({
        id: item.id,
        name: item.name,
        price: item.discountedPrice ? item.discountedPrice : item.price,
        quantity: 1,
        image: item.image,
        item_left: item.item_left,
      });
      toast.success("Product added to cart successfully!");
    } else {
      toast.info("Already in cart");
    }
  };


  return (
    <div className="p-6">
      <h2 className="text-2xl font-semibold mb-6">My Wishlist</h2>
      {wishlistItems.length === 0 && <EmptyCart title={"You doesn't have wishlist yet"} message={"Add some items for add to cart"} />}

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        {wishlistItems.map((item) => (
          <div
            key={item.id}
            className="p-4 border rounded-lg shadow-sm flex flex-col items-center"
          >
            <ProductCard
              key={item.id}
              id={item.id}
              image={item.image}
              title={item.name}
              price={item.price}
              rating={item.rating}
              ratingCount={item.totalRatings}
              discount={item.discount}
            /> 
            <div className="flex gap-3 mt-4">
              <button
                onClick={() => removeWishlistItem(item.id)}
                className="px-4 py-2 rounded-md border border-gray-300 text-gray-700 hover:bg-gray-100"
              >
                Remove
              </button>
              <button
                className={`px-4 py-2 rounded-md font-medium transition-colors ${item.in_stock
                  ? "bg-red-500 hover:bg-red-600 text-white cursor-pointer active:bg-red-700"
                  : "bg-gray-300 cursor-not-allowed"
                  }`}
                disabled={!item.in_stock}
                onClick={() => handleAddToCart(item)}
              >
                Add to cart
              </button>
            </div>
          </div>
        ))}
      </div>

    </div>
  );
}

export default WishlistPage;
